<?php
require_once __DIR__ . "/../config/conexionBDD.php"; require_once __DIR__ . "/../logica/sesion.php"; requerirLogin("login.php");
$mes = $_GET['mes'] ?? date('Y-m'); if (!preg_match('/^\d{4}-\d{2}$/', $mes)) $mes = date('Y-m');
$inicio = $mes . '-01'; $fin = date('Y-m-t', strtotime($inicio));
if ($_SERVER['REQUEST_METHOD']==='POST') {
 if (!validarCSRF($_POST['csrf_token'] ?? '')) { http_response_code(400); exit('Token de seguridad inválido.'); }
 $titulo=trim($_POST['titulo']??''); $fecha=$_POST['fecha_evento']??''; $tipo=$_POST['tipo']??'otro'; $desc=trim($_POST['descripcion']??'');
 if ($titulo!=='' && preg_match('/^\d{4}-\d{2}-\d{2}$/',$fecha)) { $stmt=$conexion->prepare('INSERT INTO evento_calendario(usuario_id,titulo,descripcion,fecha_evento,tipo) VALUES(?,?,?,?,?)'); $uid=(int)usuarioActual()['id']; $stmt->bind_param('issss',$uid,$titulo,$desc,$fecha,$tipo); $stmt->execute(); $stmt->close(); header('Location: calendario.php?mes='.substr($fecha,0,7)); exit(); }
}
$uid=(int)usuarioActual()['id'];
$sql="SELECT 'evento' origen,id,titulo,fecha_evento,tipo,estado FROM evento_calendario WHERE fecha_evento BETWEEN ? AND "."? AND (usuario_id=? OR ?=1) UNION ALL SELECT 'contrato',c.id,CONCAT('Inicio contrato #',c.id,' — ',e.razon_social),c.fecha_inicio,'inicio',c.estado FROM contrato c JOIN empresa e ON e.id=c.empresa_id WHERE c.fecha_inicio BETWEEN ? AND ? AND (c.usuario_id=? OR ?=1) ORDER BY fecha_evento";
$all=esSupervisor()?1:0; $stmt=$conexion->prepare($sql); $stmt->bind_param('ssiissii',$inicio,$fin,$uid,$all,$inicio,$fin,$uid,$all); $stmt->execute(); $eventos=$stmt->get_result();
?>
<!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Calendario de contratos</title><link rel="stylesheet" href="../css/estilos.css"></head><body><main class="contenedor"><div class="barra-acciones"><a class="btn-secundario" href="../index.php">Inicio</a><a class="btn-secundario" href="listado.php">Contratos</a></div><h1>Calendario de fechas y seguimiento</h1><form method="get"><label>Mes <input type="month" name="mes" value="<?= htmlspecialchars($mes) ?>"></label><button>Ver mes</button></form><h2>Agregar recordatorio</h2><form method="post" class="formulario"><input type="hidden" name="csrf_token" value="<?= htmlspecialchars(tokenCSRF()) ?>"><div class="campo"><label>Título *</label><input name="titulo" maxlength="150" required></div><div class="campo"><label>Fecha *</label><input type="date" name="fecha_evento" min="2000-01-01" required value="<?= htmlspecialchars($inicio) ?>"></div><div class="campo"><label>Tipo</label><select name="tipo"><option value="revision">Revisión</option><option value="seguimiento">Seguimiento</option><option value="fin_estimado">Fin estimado</option><option value="otro">Otro</option></select></div><div class="campo"><label>Descripción</label><input name="descripcion" maxlength="500"></div><button type="submit">Guardar recordatorio</button></form><h2>Eventos del mes <?= htmlspecialchars($mes) ?></h2><table class="tabla-listado"><tr><th>Fecha</th><th>Evento</th><th>Tipo</th><th>Estado</th></tr><?php while($e=$eventos->fetch_assoc()){ ?><tr><td><?= htmlspecialchars(date('d/m/Y',strtotime($e['fecha_evento']))) ?></td><td><?= htmlspecialchars($e['titulo']) ?></td><td><?= htmlspecialchars($e['tipo']) ?></td><td><?= htmlspecialchars($e['estado']) ?></td></tr><?php } ?></table><p>El calendario ayuda a controlar fechas; no reemplaza la verificación jurídica de la terminación real de la obra o labor.</p></main></body></html>